/** @scope spec://codkit/modules/vscode-extension/PROP-001#VSX-STANDARDS-PACKAGES */
// Area 8: the vibe packages of this type.
//
// The first version names none: `codkit standards load` delivers the universal
// `standards` and `agent-skills` to a patch set of this type and nothing else.
// The catalogue of this family's seams - the manifest overlay, the funnels of
// the translations, the contribution points, the webview, the telemetry switch
// - is `seams-vscode-extension`, deferred by name; when it ships it is named
// here and delivered to this type alone (##VSX-STANDARDS-PACKAGES).
export const STANDARDS_PACKAGES = [];
export const standards = { packages: STANDARDS_PACKAGES };
